entries[23805] = { ["name"] = "Schematic: Ultra-Spectropic Detection Goggles", ["text"] = "Use: Teaches you how to make Ultra-Spectropic Detection Goggles.\nRequires Outland Engineering (50)\nSell Price:\nUltra-Spectropic Detection Goggles\nBinds when equipped\nHead Cloth\n3 Armor\n+4 Stamina\n+ 6 Critical Strike\n+ 6 Haste\n+ 4 Versatility\nDurability 85 / 85\nUse: Allows you to look far into the distance.\nRequires Outland Engineering (1)\nSell Price:\nRequires Heavy Knothide Leather (4), Khorium Bar (2), Deep Peridot (2), Small Prismatic Shard (2)\nOptional Reagents: Optional Reagent Slot (#47)" }
entries[23806] = { ["name"] = "Schematic: Hyper-Vision Goggles", ["text"] = "Binds when picked up\nUse: Teaches you how to make Hyper-Vision Goggles.\nRequires Outland Engineering (60)\nSell Price:\nHyper-Vision Goggles\nBinds when equipped\nHead Leather\n5 Armor\n+5 [Agility or Intellect]\n+ 4 Critical Strike\nDurability 85 / 85\nUse: Increases your stealth detection for 15 sec. (2 Min Cooldown)\nRequires Outland Engineering (1)\nSell Price:\nRequires Heavy Knothide Leather (4), Khorium Bar (2), Nightseye (2), Large Prismatic Shard (2)\nOptional Reagents: Optional Reagent Slot (#47)" }
entries[23807] = { ["name"] = "Schematic: Adamantite Scope", ["text"] = "Use: Teaches you how to make an Adamantite Scope.\nRequires Outland Engineering (35)\nSell Price:\nAdamantite Scope\nUse: Attaches a permanent scope to a bow or gun that increases its damage by 5.\n\nAttaching this scope to a ranged weapon causes it to become soulbound. Cannot be applied to items higher than level 320.\nSell Price:\nRequires Adamantite Bar (8), Golden Draenite (2)" }
