entries[24179] = { ["name"] = "Design: Felsteel Boar", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Felsteel Boar.\nRequires Outland Jewelcrafting (70)\nRequires Lower City\n- Revered\nSell Price:\nFigurine - Felsteel Boar\nBinds when picked up\nUnique-Equipped\nTrinket\n+4 [Agility or Strength]\nUse: Summons the Felsteel Boar to fight for you for 30 seconds. (5 Min Cooldown)\nRequires Outland Jewelcrafting (70)\nSell Price:\nRequires Felsteel Bar (8), Blood Garnet (2), Primal Earth (4)\nOptional Reagents: Optional Reagent Slot (#49)" }
entries[24180] = { ["name"] = "Design: Dawnstone Crab", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Dawnstone Crab.\nRequires Outland Jewelcrafting (70)\nRequires Honor Hold\n- Revered\nSell Price:\nFigurine - Dawnstone Crab\nBinds when picked up\nUnique-Equipped\nTrinket\n+ 5 Dodge\nUse: Increases dodge by 21 for 20 sec. (2 Min Cooldown)\nRequires Outland Jewelcrafting (70)\nSell Price:\nRequires Khorium Bar (4), Dawnstone (2), Golden Draenite (4)\nOptional Reagents: Optional Reagent Slot (#49)" }
entries[24181] = { ["name"] = "Design: Living Ruby Serpent", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Living Ruby Serpent.\nRequires Outland Jewelcrafting (70)\nRequires Keepers of Time\n- Revered\nSell Price:\nFigurine - Living Ruby Serpent\nBinds when picked up\nUnique-Equipped\nTrinket\n+3 Intellect\n+4 Stamina\nUse: Increases spell power by 17 for 20 sec. (5 Min Cooldown)\nRequires Outland Jewelcrafting (70)\nSell Price:\nRequires Felsteel Bar (2), Living Ruby (2), Primal Fire (4)\nOptional Reagents: Optional Reagent Slot (#49)" }
entries[24182] = { ["name"] = "Design: Talasite Owl", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Talasite Owl.\nRequires Outland Jewelcrafting (70)\nRequires The Sha'tar\n- Revered\nSell Price:\nFigurine - Talasite Owl\nBinds when picked up\nUnique-Equipped\nTrinket\n+ 6 Versatility\nUse: Restores 100 mana over 12 sec. (5 Min Cooldown)\nRequires Outland Jewelcrafting (70)\nSell Price:\nRequires Eternium Bar (2), Talasite (2), Primal Mana (4)\nOptional Reagents: Optional Reagent Slot (#49)" }
entries[24183] = { ["name"] = "Design: Nightseye Panther", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Nightseye Panther.\nRequires Outland Jewelcrafting (70)\nRequires Cenarion Expedition\n- Revered\nSell Price:\nFigurine - Nightseye Panther\nBinds when picked up\nUnique-Equipped\nTrinket\n+4 [Agility or Strength]\nUse: Increases attack power by 18 for 12 sec. (3 Min Cooldown)\nRequires Outland Jewelcrafting (70)\nSell Price:\nRequires Hardened Adamantite Bar (6), Nightseye (2), Primal Shadow (2)\nOptional Reagents: Optional Reagent Slot (#49)" }
